INSERT INTO movies (id, title, languages, certificate, genres, duration_minutes, synopsis, cast_names, release_date, poster_from, poster_to, is_active, created_at) VALUES
  (@m + 1, 'Signal Thirteen', 'Tamil, Telugu', 'UA', 'Thriller, Mystery', 142, 'A railway signalman in Tiruchirappalli notices a train that isn''t on any timetable.', 'Arjun Selvan, Meera Nandakumar', UTC_DATE() - INTERVAL 3 DAY, '#0f766e', '#022c22', TRUE, UTC_TIMESTAMP(6)),
  (@m + 2, 'Pearl City Nights', 'Tamil', 'U', 'Romance, Drama', 136, 'Two pearl divers'' children meet again at the Thoothukudi harbour festival.', 'Kavin Raj, Ishaani Prabhu', UTC_DATE() - INTERVAL 15 DAY, '#be185d', '#4c0519', TRUE, UTC_TIMESTAMP(6)),
  (@m + 3, 'Rockfort Diaries', 'Tamil, English', 'UA', 'Comedy, Drama', 128, 'Five college friends reunite to save the tea shop where they used to bunk classes.', 'Surya Prakash, Diya Menon', UTC_DATE() - INTERVAL 4 DAY, '#c2410c', '#431407', TRUE, UTC_TIMESTAMP(6)),
  (@m + 4, 'The Monsoon Ferry', 'Tamil, Malayalam', 'U', 'Family, Drama', 122, 'A grandmother''s last ferry ride across the backwaters brings a scattered family together.', 'Lakshmi Iyer, Vetri Maran', UTC_DATE() - INTERVAL 19 DAY, '#1d4ed8', '#172554', TRUE, UTC_TIMESTAMP(6)),
  (@m + 5, 'Starling and the Kite', 'Tamil, Telugu, Hindi', 'U', 'Animation, Adventure', 104, 'A young starling teams up with a runaway kite to find its way home before Pongal.', 'Voice cast: Nila Arun, Hari Kumar', UTC_DATE() - INTERVAL 8 DAY, '#7c3aed', '#2e1065', TRUE, UTC_TIMESTAMP(6)),
  (@m + 6, 'Midnight Toll Plaza', 'Tamil, Telugu', 'A', 'Action, Crime', 158, 'One night at a highway toll plaza, a booth operator becomes the only witness to a heist.', 'Dhruv Shankar, Anaya Pillai', UTC_DATE() - INTERVAL 13 DAY, '#b91c1c', '#1c1917', TRUE, UTC_TIMESTAMP(6)),
  (@m + 7, 'Boundary Line Boys', 'Tamil', 'U', 'Sports, Drama', 145, 'A village cricket team from Salem gets one shot at the state tournament.', 'Mithran Das, Keerthi Ravi', UTC_DATE() - INTERVAL 1 DAY, '#15803d', '#052e16', TRUE, UTC_TIMESTAMP(6)),
  (@m + 8, 'Orbit Café', 'English, Tamil, Hindi', 'UA', 'Sci-fi, Comedy', 118, 'A Chennai café accidentally starts serving coffee to visitors from the future.', 'Rohan Varma, Sana Iqbal', UTC_DATE() - INTERVAL 18 DAY, '#0369a1', '#082f49', TRUE, UTC_TIMESTAMP(6));
