-- BookEasy demo cinemas, showtimes, restaurants and cafés (Tamil Nadu). Load after demo-tamilnadu.sql.
-- GENERATED by backend/seed/generate_movies_dining.py - edit the script, not this file.
-- Everything here is fictional. Owners: demo.venue.*@example.com / Demo@1234. DO NOT run against production.
-- Showtimes cover the 21 days after loading; load the file again for fresh ones.
SET NAMES utf8mb4;
START TRANSACTION;

-- Remove earlier demo venues and movies
CREATE TEMPORARY TABLE demo_venue_users AS SELECT id FROM users WHERE email LIKE 'demo.venue.%@example.com';
CREATE TEMPORARY TABLE demo_venue_orgs AS SELECT o.id FROM organizations o JOIN organization_owners oo ON oo.organization_id = o.id WHERE oo.user_id IN (SELECT id FROM demo_venue_users);
DELETE FROM appointments WHERE organization_id IN (SELECT id FROM demo_venue_orgs);
DELETE FROM organizations WHERE id IN (SELECT id FROM demo_venue_orgs);
DELETE FROM users WHERE id IN (SELECT id FROM demo_venue_users);
DELETE FROM movies WHERE title IN ('Signal Thirteen', 'Pearl City Nights', 'Rockfort Diaries', 'The Monsoon Ferry', 'Starling and the Kite', 'Midnight Toll Plaza', 'Boundary Line Boys', 'Orbit Café');
DROP TEMPORARY TABLE demo_venue_users;
DROP TEMPORARY TABLE demo_venue_orgs;

SET @u = (SELECT COALESCE(MAX(id), 0) FROM users);
SET @o = (SELECT COALESCE(MAX(id), 0) FROM organizations);
SET @b = (SELECT COALESCE(MAX(id), 0) FROM organization_branches);
SET @s = (SELECT COALESCE(MAX(id), 0) FROM services);
SET @m = (SELECT COALESCE(MAX(id), 0) FROM movies);
SET @sc = (SELECT COALESCE(MAX(id), 0) FROM cinema_screens);


















COMMIT;
-- 8 movies, 8 cinemas, 16 screens, 1344 shows, 12 restaurants/cafés, 83 dishes
